const message = $input.first().json.body.message;
if (message.type !== 'tool-calls' || !Array.isArray(message.toolCallList) || !message.toolCallList.length) throw new Error('Expected a non-empty tool-calls message');
const seen = new Set();
return message.toolCallList.map(call => {
  if (typeof call.id !== 'string' || !call.id || seen.has(call.id)) throw new Error('Each tool call needs a unique ID');
  seen.add(call.id);
  if (call.function?.name !== 'lookupOrders' || typeof call.function.arguments?.customerId !== 'string' || !/^[a-zA-Z0-9-]+$/.test(call.function.arguments.customerId)) throw new Error('Expected lookupOrders with a customerId');
  return {json: {toolCallId: call.id, customerId: call.function.arguments.customerId}, pairedItem: {item: 0}};
});

const results = $input.all().map((item, index) => {
  const { toolCallId } = $('Split tool calls').itemMatching(index).json;
  if (item.json.statusCode === 503) return {toolCallId, error: 'Order service temporarily unavailable. Please try again later.'};
  if (item.json.statusCode !== 200) return {toolCallId, error: 'Order lookup failed.'};
  if (!Array.isArray(item.json.body?.orders)) return {toolCallId, error: 'Order service returned an invalid response.'};
  return {toolCallId, result: JSON.stringify({orders: item.json.body.orders})};
});
return [{json: {results}}];
